def source(local_id: str, url: str, publisher: str, title: str, source_type: str = "official_product_page") -> dict[str, Any]:
    return {
        "local_id": local_id,
        "url": url,
        "source_type": source_type,
        "publisher": publisher,
        "title": title,
        "accessed_at": NOW,
        "language": "it",
        "metadata": {"retrieval_method": "official_web_page_review", "rights_basis": "publicly_available", "snapshot_date": "2026-09-10"},
    }


def build_bundle(agent_id: str, record_id: str, title_scope: str, products: list[dict[str, Any]]) -> dict[str, Any]:
    entities: list[dict[str, Any]] = []
    sources: list[dict[str, Any]] = []
    documents: list[dict[str, Any]] = []
    classifications: list[dict[str, Any]] = []
    features: list[dict[str, Any]] = []
    technical: list[dict[str, Any]] = []
    facts: list[dict[str, Any]] = []
    claims: list[dict[str, Any]] = []
    notes: list[dict[str, Any]] = []
    for p in products:
        company_ref = f"company:{p['slug']}"
        product_ref = f"product:{p['slug']}"
        main_ref = f"source:{p['slug']}:main"
        price_ref = f"source:{p['slug']}:price"
        entities.append({"local_id": company_ref, "entity_type": "company", "name": p["company"], "website": p["url"], "headquarters_country": p["country"]})
        entities.append({"local_id": product_ref, "entity_type": "product", "company_ref": company_ref, "name": p["name"], "slug": p["slug"], "website": p["url"], "deployment": [term[2] for term in p["tech"] if term[0] == "deployment_model"], "description": p["description"]})
        sources.append(source(main_ref, p["url"], p["company"], f"{p['name']} — pagina ufficiale"))
        text_parts = [p["excerpt"], f"Sales motion osservata: {json.dumps(p['sales'], ensure_ascii=False)}.", f"Onboarding dichiarato: {json.dumps(p['onboarding'], ensure_ascii=False)}.", f"Supporto dichiarato: {json.dumps(p['support'], ensure_ascii=False)}."]
        if p["need"]:
            text_parts.append(f"Bisogno cliente dichiarato o rappresentato: {p['need']}")
        if p["price_url"]:
            sources.append(source(price_ref, p["price_url"], p["company"], f"{p['name']} — pricing/FAQ ufficiale", "official_pricing_page"))
            documents.append({"local_id": f"document:{p['slug']}:price", "source_ref": price_ref, "title": f"{p['name']} — pricing/FAQ", "document_type": "web_page", "extraction_method": "web_text_excerpt", "text": p["price_excerpt"] or "Pagina ufficiale di pricing consultata."})
        documents.append({"local_id": f"document:{p['slug']}:main", "source_ref": main_ref, "title": f"{p['name']} — snapshot di ricerca", "document_type": "web_page", "extraction_method": "web_text_excerpt", "text": " ".join(text_parts)})
        for kind, slug, name in [("category", p["category"], p["category"]), ("vertical", p["vertical"], p["vertical"])] + [("segment", seg, seg) for seg in p["segments"]]:
            classifications.append({"subject_ref": product_ref, "kind": kind, "term_slug": slug, "term_name": name, "confidence": "high", "source_ref": main_ref, "evidence_excerpt": p["excerpt"][:300]})
        for slug, name, group, level in p["features"]:
            features.append({"subject_ref": product_ref, "feature_slug": slug, "feature_name": name, "feature_group": group, "support_level": level, "confidence": "high", "source_ref": main_ref, "evidence_excerpt": p["excerpt"][:300]})
        for kind, slug, name, relationship in p["tech"]:
            technical.append({"subject_ref": product_ref, "kind": kind, "term_slug": slug, "term_name": name, "relationship_type": relationship, "confidence": "high" if relationship != "unknown" else "low", "source_ref": main_ref, "evidence_excerpt": p["excerpt"][:300]})
        fact_source = price_ref if p["price_url"] else main_ref
        for predicate, value in p["pricing"]:
            facts.append({"subject_ref": product_ref, "predicate": predicate, "value": value, "value_kind": "observed", "confidence": "high", "source_ref": fact_source, "evidence_excerpt": (p["price_excerpt"] or p["excerpt"])[:350]})
        for predicate, value in [("sales.motion", p["sales"]), ("onboarding.model", p["onboarding"]), ("support.model", p["support"])]:
            facts.append({"subject_ref": product_ref, "predicate": predicate, "value": value, "value_kind": "observed", "confidence": "medium", "source_ref": main_ref, "evidence_excerpt": p["excerpt"][:300]})
        claims.extend([
            {"subject_ref": product_ref, "claim_type": "observed", "predicate": "positioning", "statement": p["excerpt"], "confidence": "high", "source_ref": main_ref, "evidence_excerpt": p["excerpt"][:350]},
            {"subject_ref": product_ref, "claim_type": "observed", "predicate": "customer_need", "statement": p["need"], "confidence": "medium", "source_ref": main_ref, "evidence_excerpt": p["excerpt"][:300]},
            {"subject_ref": product_ref, "claim_type": "inferred", "predicate": "evidence_gap", "statement": p["gap"], "assessment": "diligence_gap", "methodology": "Review delle pagine ufficiali elencate nel bundle; l'assenza di pubblicazione non viene interpretata come assenza di funzionalità.", "confidence": "low", "source_ref": main_ref, "evidence_excerpt": "Pagine ufficiali consultate il 2026-09-10."},
        ])
        notes.append({"subject_ref": product_ref, "note_type": "data_quality", "text": "Financial metrics dell'operatore non aggiunte: nessuna fonte societaria affidabile è stata inclusa in questo bundle. La lacuna richiede un ciclo separato di bilanci/registro.", "confidence": "high"})
        notes.append({"subject_ref": product_ref, "note_type": "research_note", "text": "Snapshot di discovery hospitality e verticali adiacenti; il prodotto è candidato nuovo rispetto alla query del catalogo effettuata prima della raccolta.", "confidence": "medium"})
    return {"schema_version": "1.0", "record_id": record_id, "created_at": NOW, "created_by": {"agent_id": agent_id}, "scope": {"country": "IT", "language": "it", "research_type": "hospitality_discovery_and_enrichment", "vertical_scope": title_scope}, "entities": entities, "sources": sources, "documents": documents, "classifications": classifications, "features": features, "technical_characteristics": technical, "financial_metrics": [], "facts": facts, "claims": claims, "notes": notes}


