def build_commercial() -> dict[str, Any]:
    products: list[dict[str, Any]] = []
    for slug, name, company, url, category, commercial_text in COMMERCIAL:
        vertical = "restaurant_food_service" if category == "restaurant_pos" else "hospitality"
        products.append(item("commercial", f"commercial-{slug}", name, company, url, vertical, category, ["existing_hospitality_catalogue"], commercial_text, [], [], pricing=[("pricing.observed", commercial_text)], sales={"motion": "demo_or_contact"}, onboarding={"model": "not fully disclosed in reviewed page"}, support={"model": "not fully disclosed in reviewed page"}, need="Copertura commerciale da completare per confrontare prezzo, vendita, onboarding e supporto.", gap="Le fonti pubbliche non consentono di confrontare tutti i driver di prezzo, SLA, API e migrazione; è una lacuna di evidenza."))
    bundle = build_bundle("fleet-hosp-commercial", "fleet-hospitality-2026-09-commercial-001", "commercial_enrichment_existing_hospitality_products", products)
    company_ref = "company:commercial-bedzzle"
    # The two Zucchetti Hospitality products share the same operator in the catalogue; add
    # one reported company metric from the already-cached financial source.
    bundle["entities"].append({"local_id": "company:zucchetti-hospitality-finance", "entity_type": "company", "name": "Zucchetti Hospitality S.r.l.", "identifiers": {"vat_id": "02894171202"}, "website": "https://www.zucchetti.it/", "headquarters_country": "IT"})
    fin_ref = "source:zucchetti-hospitality-finance"
    bundle["sources"].append(source(fin_ref, "https://www.aziende.it/zucchetti-hospitality-s-r-l", "Aziende.it / Ad Intend S.r.l.", "Zucchetti Hospitality S.r.l. — dati economici 2025", "directory"))
    bundle["documents"].append({"local_id": "document:zucchetti-hospitality-finance", "source_ref": fin_ref, "title": "Zucchetti Hospitality — snapshot finanziario", "document_type": "web_page", "extraction_method": "reused_catalogue_excerpt", "text": "La fonte secondaria dichiara per Zucchetti Hospitality S.r.l. (P.IVA 02894171202) fatturato 2025 di 74.295.721 euro, perdita 3.933.533 euro e 628 dipendenti; dato riferito alla società, non al Gruppo Zucchetti."})
    bundle["financial_metrics"] = [
        {"subject_ref": "company:commercial-bedzzle", "metric": "revenue", "period_year": 2025, "value": {"exact": 74295721}, "currency": "EUR", "value_kind": "reported", "confidence": "medium", "source_ref": fin_ref, "evidence_excerpt": "Fatturato 2025: €74.295.721; fonte secondaria che dichiara Registro Imprese."},
        {"subject_ref": "company:commercial-bedzzle", "metric": "net_income", "period_year": 2025, "value": {"exact": -3933533}, "currency": "EUR", "value_kind": "reported", "confidence": "medium", "source_ref": fin_ref, "evidence_excerpt": "Perdita 2025: €3.933.533."},
        {"subject_ref": "company:commercial-bedzzle", "metric": "employees", "period_year": 2025, "value": {"exact": 628}, "value_kind": "reported", "confidence": "medium", "source_ref": fin_ref, "evidence_excerpt": "Dipendenti 2025: 628."},
    ]
    bundle["notes"].append({"subject_ref": "company:commercial-bedzzle", "note_type": "data_quality", "text": "Le metriche sono riferite a Zucchetti Hospitality S.r.l. e non al Gruppo Zucchetti; la fonte è una directory finanziaria che dichiara Registro Imprese e non un bilancio ufficiale allegato.", "confidence": "high"})
    return bundle


def main() -> int:
    if OUT.exists():
        for path in sorted(OUT.iterdir()):
            if path.is_dir() and path.name.startswith("fleet-"):
                shutil.rmtree(path)
    buckets = {
        "pms": "fleet-hosp-pms",
        "openair": "fleet-hosp-openair",
        "foodpos": "fleet-hosp-foodpos",
        "channel": "fleet-hosp-channel",
        "tech": "fleet-hosp-tech",
        "customer": "fleet-hosp-customer",
        "adjacent": "fleet-adjacent",
    }
    OUT.mkdir(parents=True, exist_ok=True)
    for bucket, agent_id in buckets.items():
        rows = [p for p in PRODUCTS if p["bucket"] == bucket]
        path = OUT / agent_id / f"2026-09-10-{bucket}-fleet-001.json"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(build_bundle(agent_id, f"fleet-hospitality-2026-09-{bucket}-001", bucket, rows), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        print(f"{path}: {len(rows)} new products")
    path = OUT / "fleet-hosp-commercial" / "2026-09-10-commercial-enrichment-001.json"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(build_commercial(), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"{path}: {len(COMMERCIAL)} existing hospitality products enriched")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
